def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if budget <= 0:
        return 0.0

    if not alive:
        base = DAILY_SALARY * 0.25
        if no_water >= 1 or hp <= 3:
            base = DAILY_SALARY * 0.55
        return float(max(0.0, min(budget, base)))

    yesterday_bids = []
    urgent_opponents = 0
    rich_opponents = 0
    for opp in alive:
        if opp.get('budget', 0) > budget:
            rich_opponents += 1
        if opp.get('no_water_days', 0) >= 1 or opp.get('hp', 10) <= 3:
            urgent_opponents += 1
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(float(prev['bid']))

    highest_prev = max(yesterday_bids) if yesterday_bids else 0.0
    avg_prev = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 0.0

    slots = int(max(1, supply // WATER_REQ))
    contested = len(alive) + 1 > slots
    loose = len(alive) + 1 <= slots

    danger = 0
    if hp <= 2:
        danger += 3
    elif hp <= 4:
        danger += 2
    elif hp <= 6:
        danger += 1

    if no_water >= 2:
        danger += 3
    elif no_water >= 1:
        danger += 2

    if supply <= MIN_SUPPLY + 1:
        danger += 2
    elif supply <= 18:
        danger += 1

    if urgent_opponents >= slots:
        danger += 1

    if loose:
        bid = DAILY_SALARY * 0.22
        if danger >= 4:
            bid = DAILY_SALARY * 0.48
        elif danger >= 2:
            bid = DAILY_SALARY * 0.34
        if highest_prev > 0 and highest_prev < DAILY_SALARY * 0.5:
            bid = max(bid, highest_prev + 1.0)
        return float(max(0.0, min(budget, bid)))

    if danger >= 6:
        target = max(DAILY_SALARY * 1.05, highest_prev + 2.5, avg_prev + 4.0)
        bid = min(budget, target)
        return float(max(0.0, bid))

    if danger >= 4:
        target = max(DAILY_SALARY * 0.82, highest_prev + 1.5)
        if highest_prev >= 140:
            target = DAILY_SALARY * 0.9
        bid = min(budget, target)
        return float(max(0.0, bid))

    if supply >= 24:
        bid = DAILY_SALARY * 0.18
    elif supply >= 21:
        bid = DAILY_SALARY * 0.24
    elif supply >= 18:
        bid = DAILY_SALARY * 0.32
    else:
        bid = DAILY_SALARY * 0.42

    if highest_prev > 0:
        if highest_prev >= 150:
            bid = min(bid, DAILY_SALARY * 0.35)
        elif highest_prev >= 100:
            bid = min(bid, DAILY_SALARY * 0.4)
        else:
            bid = max(bid, highest_prev + 1.0)

    if rich_opponents >= 2 and danger <= 2:
        bid *= 0.85

    if day >= 8 and hp >= 6 and no_water == 0:
        bid *= 0.9

    return float(max(0.0, min(budget, bid)))

def get_bid(day_context, my_status, opponents_status):
    MY_WATER_REQ = 1 
    MY_DAILY_SALARY = 150
    EPISODE_DAYS = 10 
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    current_day = day_context['day']
    current_supply = day_context['supply']
    my_hp = my_status['hp']
    my_budget = my_status['budget']
    my_no_water_days = my_status['no_water_days']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    if not alive_opponents:
        return min(my_budget, MY_DAILY_SALARY * 0.1)

    # --- Determine base bid based on self-preservation ---
    if my_hp <= 2 or my_no_water_days > 0:
        base_bid = MY_DAILY_SALARY * 0.98 
    elif my_hp <= 4:
        base_bid = MY_DAILY_SALARY * 0.85
    else:
        base_bid = MY_DAILY_SALARY * 0.65 

    # --- Adjust bid based on opponent behavior (yesterday's trace) ---
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        if highest_prev_bid >= MY_DAILY_SALARY * 0.8:
            if current_supply < (MIN_SUPPLY + MAX_SUPPLY) / 2:
                base_bid = max(base_bid, highest_prev_bid + 7)
            else:
                base_bid = max(base_bid, highest_prev_bid + 3)
        elif highest_prev_bid >= MY_DAILY_SALARY * 0.5:
            base_bid = max(base_bid, highest_prev_bid + 2)
        elif num_alive_opponents > 1:
            base_bid = max(base_bid, highest_prev_bid + 5)

    # --- Adjust bid for end-game ---
    remaining_days = EPISODE_DAYS - current_day
    if remaining_days <= 2:
        if my_hp <= remaining_days + 1:
            base_bid = max(base_bid, MY_DAILY_SALARY * 1.1)
        else:
            base_bid = max(base_bid, MY_DAILY_SALARY * 0.9)

    # --- Final bid: ensure it doesn't exceed budget and is at least 1 ---
    final_bid = min(my_budget, base_bid)
    final_bid = max(1.0, final_bid)

    return final_bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = int(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = [o for o in opponents_status.values() if o.get('alive', False)]
    if not alive_opps:
        return min(budget, DAILY_SALARY * 0.4)

    # Extract yesterday bids from each opponent's previous_trace
    prev_bids = []
    for opp in alive_opps:
        pt = opp.get('previous_trace', {}) or {}
        b = pt.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    # If we have no trace bids, fall back to conservative bidding
    if not prev_bids:
        base = DAILY_SALARY * (0.65 if hp > 3 else 0.9)
        return min(budget, base)

    highest_prev_bid = max(prev_bids)
    avg_prev_bid = sum(prev_bids) / float(len(prev_bids))

    # Determine aggressiveness based on supply and our risk
    # Mid scenario supply ~15-25; with WATER_REQ=8, we can estimate scarcity.
    scarcity_ratio = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY + 1e-9)  # 0..1-ish

    # If we're in danger, bid to secure water.
    if hp <= 2 or no_water_days >= 2:
        target = max(DAILY_SALARY * 0.75, avg_prev_bid * (0.95 + 0.1 * scarcity_ratio))
        return min(budget, max(0.0, target))

    # Otherwise, pressure above the typical surviving bidders (Cindy/David) without matching Alex/Bob extremes.
    # Use a threshold derived from yesterday: if someone bid very high, we slightly overbid; else we bid near avg.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        # They were willing to spend heavily; we must compete.
        target = avg_prev_bid * (1.05 + 0.15 * scarcity_ratio)
    else:
        # They were less extreme; bid enough to win but keep budget.
        target = max(DAILY_SALARY * 0.55, avg_prev_bid * (0.98 + 0.10 * scarcity_ratio))

    # Cap by budget and keep within reasonable bounds.
    # Also, if budget is low, don't overcommit.
    if budget <= DAILY_SALARY * 0.6:
        target = min(target, budget * 0.85)

    # Final clamp to budget
    if target < 0.0:
        target = 0.0
    return min(budget, target)
